#!/usr/bin/env python3
import csv,json,math,statistics
from pathlib import Path
import numpy as np
P=Path('/scratch/dexuan1/vmcnet/experiments/N2_rank400_longtime_pilot');OUT=P/'results';F=Path('/scratch/dexuan1/runs/N2_rank400_longtime_pilot_frozen');train={r['variant']:r for r in csv.DictReader(open(OUT/'stage2_summary.csv'))};stable=json.loads((OUT/'release_frozen.json').read_text())['stable_tasks'];names=['A_beta02_control','B_beta01_fixed','C_beta_decay','D_residual_optimal','E_capped_near_tail','F_rank600_hard'];rows=[]
for i in stable:
 n=names[i];ev=F/n/'eval';stats=json.loads((ev/'statistics.json').read_text());le=np.loadtxt(ev/'local_energies.txt').reshape(-1);assert le.size==500*4096 and np.isfinite(le).all();acc=np.loadtxt(ev/'accept_ratio.txt').reshape(-1)
 t=train[n];dev=np.abs(le+109.5);rows.append(dict(variant=n,frozen_energy=stats['average'],frozen_sem=stats['std_err'],frozen_raw_variance=stats['variance'],iat=stats['integrated_autocorrelation'],ess=le.size/stats['integrated_autocorrelation'],acceptance=float(acc.mean()),q001=float(np.quantile(le,.001)),q01=float(np.quantile(le,.01)),q99=float(np.quantile(le,.99)),q999=float(np.quantile(le,.999)),minimum=float(le.min()),maximum=float(le.max()),fraction_absdev_gt5=float(np.mean(dev>5)),fraction_absdev_gt10=float(np.mean(dev>10)),fraction_absdev_gt20=float(np.mean(dev>20)),nonfinite=0,tail100_raw_variance=float(t['tail100_raw_variance']),tail100_clipped_variance=float(t['tail100_clipped_variance']),median_seconds_epoch=float(t['median_seconds_epoch']),peak_gpu_mib=float(t['peak_gpu_mib']),ratio_mean=float(t['ratio_mean']),cap_active_fraction=float(t['cap_active_fraction']),residual_after_mean=float(t['residual_after_mean'])))
rows.sort(key=lambda x:x['frozen_raw_variance']);
with (OUT/'final_summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
best_var=rows[0];best_tail=min(rows,key=lambda x:max(abs(x['q001']+109.5),abs(x['q999']+109.5)));best_cost=min(rows,key=lambda x:x['frozen_raw_variance']*x['median_seconds_epoch']);best_res=min(rows,key=lambda x:x['residual_after_mean'] if x['residual_after_mean']>0 else math.inf)
decision={'best_raw_variance':best_var['variant'],'best_tail_control':best_tail['variant'],'best_runtime_variance_tradeoff':best_cost['variant'],'best_residual_accuracy':best_res['variant']};(OUT/'decision.json').write_text(json.dumps(decision,indent=2)+'\n');lines=['# N2 rank400 long-time pilot','', '|variant|frozen energy ± SEM|raw variance|IAT|ESS|q0.1%|q99.9%|tail100 raw variance|s/epoch|peak MiB|','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|'];
for r in rows:lines.append(f"|{r['variant']}|{r['frozen_energy']:.8f} ± {r['frozen_sem']:.2g}|{r['frozen_raw_variance']:.5g}|{r['iat']:.3f}|{r['ess']:.0f}|{r['q001']:.4f}|{r['q999']:.4f}|{r['tail100_raw_variance']:.5g}|{r['median_seconds_epoch']:.3f}|{r['peak_gpu_mib']:.0f}|")
lines+=['','```json',json.dumps(decision,indent=2),'```'];(OUT/'report.md').write_text('\n'.join(lines)+'\n');print(json.dumps(decision,indent=2))
